function render(){document.getElementById('root').innerHTML=db.user?appView():loginView();if(db.presentations.active)renderPresentation();}
function loginView(){return `<div class="login"><section class="loginHero"><div class="brandLock"><div class="brandMark"></div><div class="brandText"><b>ECOSISTEMA EDUCATIVO 3.0</b><small>Libro · Currículum · Evaluación · Recursos · Comunidad</small></div></div><div class="heroCopy"><span class="eyebrow">DEMO DE PRODUCTO · CAPCHILE / FRAGUACONNECT</span><h1>Una plataforma.<br><span>Toda la comunidad educativa.</span></h1><p>El Libro de Clases 3.0 evoluciona hacia un ecosistema: planifica con OA, crea y corrige evaluaciones, accede a recursos, automatiza asistencia, registra retiros y convierte datos cotidianos en acciones útiles.</p><div class="heroPills"><span class="heroPill">📘 Libro físico-digital</span><span class="heroPill">🎯 Currículum/OA</span><span class="heroPill">🧪 Evaluaciones</span><span class="heroPill">📡 RFID</span><span class="heroPill">🧰 Recursos</span><span class="heroPill">📈 Control Tower</span></div></div><div style="font-size:11px;color:#b8cad8;position:relative;z-index:2">Versión de prueba · datos 100% ficticios · no usar información personal real</div></section><section class="loginPane"><div class="loginCard"><span class="eyebrow">Acceso DEMO</span><h2>Entrar al Ecosistema 3.0</h2><p class="muted">Prueba el flujo como Docente, UTP, Dirección, Inspectoría o Sostenedor.</p><label>Correo</label><input id="email" class="field" value="docente@demo.cl"><label>Clave</label><input id="pass" type="password" class="field" value="demo123"><label>Perfil</label><select id="role" class="field"><option>Docente</option><option>UTP</option><option>Dirección</option><option>Inspectoría</option><option>Sostenedor / DAEM / SLEP</option></select><button class="btn primary full" style="margin-top:18px" onclick="login()">Ingresar</button><div class="demoNote"><b>Clave:</b> demo123. El módulo Currículum muestra un catálogo de demostración con arquitectura preparada para carga masiva del catálogo oficial; no representa aún la totalidad de los OA del Mineduc.</div></div></section></div>`}
function login(){if(document.getElementById('pass').value!=='demo123'){alert('Usa la clave demo123');return;}const role=document.getElementById('role').value;db.user={name:role==='Docente'?'Marcela Soto Muñoz':role==='UTP'?'Carolina Méndez':role==='Dirección'?'Alejandro Rivas':role==='Inspectoría'?'Daniela Paredes':'Paula Contreras',role,email:document.getElementById('email').value};save();route='inicio';render();}
function logout(){db.user=null;save();render();}
function go(r){route=r;render();window.scrollTo({top:0,behavior:'smooth'});}
function appView(){const nav= NAV.map(([r,i,t])=>`<button class="navItem ${route===r?'active':''}" onclick="go('${r}')"><span class="navIcon">${i}</span><span class="navText">${t}</span></button>`).join('');return `<div class="shell"><aside class="sidebar"><div class="sideBrand"><div class="brandMark"></div><div class="brandText"><b>ECOSISTEMA 3.0</b><small>${esc(db.school.name)}</small></div></div><div class="navGroup"><div class="navLabel">Trabajo diario</div>${nav.slice(0,nav.indexOf('')).length?nav:nav}</div><div class="sideFoot">Libro 3.0 · Ecosistema de apoyo a la comunidad educativa.<br>DEMO UX · ${db.school.year}</div></aside><main class="main"><header class="topbar"><div class="crumb"><b>${titleFor(route)}</b><small>${esc(db.school.course)} · ${esc(db.school.year)} · ${esc(db.school.name)}</small></div><div class="topActions"><span class="sync"><i></i> Sincronizado · DEMO</span><button class="btn small ghost" onclick="startPresentation()">▶ Presentación 10 min</button><button class="btn small ghost" onclick="resetDemo()">↺ Reiniciar</button><div class="user"><div class="avatar">${initials(db.user.name)}</div><div class="utxt"><b style="font-size:11px">${esc(db.user.name)}</b><small>${esc(db.user.role)}</small></div></div><button class="btn small dark" onclick="logout()">Salir</button></div></header>${pageFor(route)}</main></div>`}
function titleFor(r){return ({inicio:'Inicio del ecosistema',libro:'Libro de Clases 3.0',planificador:'Planificador pedagógico',curriculum:'Currículum y Objetivos de Aprendizaje',evaluaciones:'Creador de instrumentos de evaluación',corrector:'Corrector de instrumentos',recursos:'Biblioteca pedagógica',rfid:'Asistencia inteligente RFID',retiros:'Registro de retiro de estudiantes',estudiantes:'Student 360',comunidad:'Comunidad educativa',reportes:'Reportes y Control Tower'})[r]||'Ecosistema 3.0';}
function pageFor(r){return ({inicio:homePage,libro:bookPage,planificador:plannerPage,curriculum:curriculumPage,evaluaciones:evaluationPage,corrector:correctorPage,recursos:resourcesPage,rfid:rfidPage,retiros:withdrawalPage,estudiantes:studentsPage,comunidad:communityPage,reportes:reportsPage})[r]();}

