function bookTabs(){return `<div class="bookTabs"><button class="bookTab ${bookSpread===1?'active':''}" onclick="bookSpread=1;render()">DATOS</button><button class="bookTab ${bookSpread===2?'active':''}" onclick="bookSpread=2;render()">ASISTENCIA</button><button class="bookTab ${bookSpread===3?'active':''}" onclick="bookSpread=3;render()">LECCIONARIO</button><button class="bookTab ${bookSpread===4?'active':''}" onclick="bookSpread=4;render()">EVALUACIÓN</button></div>`}
function bookSpreadView(){if(bookSpread===1)return bookData();if(bookSpread===2)return bookAttendance();if(bookSpread===3)return bookTeaching();return bookEval();}
function paper(content,n,side){return `<section class="paper ${side}"><div class="watermark">LIBRO<br>3.0</div>${content}<div class="pageNo">${n}</div></section>`}
function bookData(){const rows=db.students.slice(0,15).map(s=>`<tr><td>${s.id}</td><td>${esc(s.name)}</td><td>${s.run}</td></tr>`).join('');const rows2=db.students.slice(15).map(s=>`<tr><td>${s.id}</td><td>${esc(s.name)}</td><td>${esc(s.guardian)}</td><td>${s.phone}</td></tr>`).join('');return `<div class="spread">${paper(`<div class="bookTitle">Identificación del curso</div><div class="paperInfo"><div class="line"><b>Establecimiento</b><span>${db.school.name}</span></div><div class="line"><b>RBD</b><span>${db.school.rbd}</span></div><div class="line"><b>Curso</b><span>${db.school.course}</span></div><div class="line"><b>Año</b><span>${db.school.year}</span></div><div class="line"><b>Profesor(a) jefe</b><span>${db.school.teacher}</span></div></div><div class="paperBar">Nómina del curso</div><table class="paperTable"><thead><tr><th>N°</th><th>Estudiante</th><th>RUN/IPE</th></tr></thead><tbody>${rows}</tbody></table>`,1,'left')}${paper(`<div class="bookTitle">Apoderados y contacto</div><div class="paperBar">Continuación de nómina</div><table class="paperTable"><thead><tr><th>N°</th><th>Estudiante</th><th>Apoderado</th><th>Teléfono</th></tr></thead><tbody>${rows2}</tbody></table><div class="paperBar" style="margin-top:9px">Resumen</div><div class="paperInfo"><div class="line"><b>Matrícula</b><span>30 estudiantes</span></div><div class="line"><b>Jornada</b><span>Completa</span></div><div class="line"><b>Estado sync</b><span>Actualizado</span></div></div>`,2,'right')}</div>`}
function bookAttendance(){const days=[1,2,3,4,5,8,9,10,11,12];const marks=s=>days.map((d,j)=>{let x='P';if((s.id+d)%19===0)x='A';else if((s.id*2+d)%23===0)x='T';else if((s.id+d*3)%29===0)x='J';return `<td>${x}</td>`}).join('');const t=(list)=>`<table class="paperTable"><thead><tr><th>N°</th><th>Nombre estudiante</th>${days.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${list.map(s=>`<tr><td>${s.id}</td><td>${esc(s.name)}</td>${marks(s)}</tr>`).join('')}</tbody></table>`;return `<div class="spread">${paper(`<div class="bookTitle">Asistencia mensual · Octubre</div><div class="paperInfo"><div class="line"><b>Curso</b><span>${db.school.course}</span></div><div class="line"><b>Convenciones</b><span>P Presente · A Ausente · T Atraso · J Justificado</span></div></div>${t(db.students.slice(0,15))}`,3,'left')}${paper(`<div class="bookTitle">Asistencia mensual</div>${t(db.students.slice(15))}<div class="paperBar" style="margin-top:9px">Automatización</div><div class="paperInfo"><div class="line"><b>Fuente</b><span>Presence Engine RFID UHF</span></div><div class="line"><b>Excepciones</b><span>${db.students.filter(s=>s.today!=='Presente').length}</span></div><div class="line"><b>Firma</b><span>${db.attendanceSigned?'Firmada':'Pendiente'}</span></div></div>`,4,'right')}</div>`}
function bookTeaching(){const rows=db.plans.map((p,i)=>`<tr><td>${i+1}/10</td><td>${p.subject}</td><td>${p.oa}</td><td>${p.title}</td></tr>`).join('');return `<div class="spread">${paper(`<div class="bookTitle">Registro del desarrollo de contenidos</div><table class="paperTable"><thead><tr><th>Fecha</th><th>Asignatura</th><th>OA</th><th>Objetivo / foco</th></tr></thead><tbody>${rows}</tbody></table>`,5,'left')}${paper(`<div class="bookTitle">Actividades desarrolladas</div><table class="paperTable"><thead><tr><th>Asignatura</th><th>Actividad</th><th>Evidencia</th><th>Firma</th></tr></thead><tbody>${db.plans.map(p=>`<tr><td>${p.subject}</td><td>${p.title}</td><td>${p.evidence}</td><td>✓ ${initials(db.school.teacher)}</td></tr>`).join('')}</tbody></table><div class="paperBar" style="margin-top:9px">Vínculo con planificador</div><div class="paperInfo"><div class="line"><b>Planificaciones</b><span>${db.plans.length} sincronizadas</span></div><div class="line"><b>OA</b><span>Traídos desde Currículum</span></div></div>`,6,'right')}</div>`}
function bookEval(){const rows=db.instruments.map(x=>`<tr><td>${x.id}</td><td>${x.subject}</td><td>${x.name}</td><td>${x.questions.reduce((a,q)=>a+q.points,0)} pts</td></tr>`).join('');return `<div class="spread">${paper(`<div class="bookTitle">Registro de evaluaciones</div><table class="paperTable"><thead><tr><th>ID</th><th>Asignatura</th><th>Instrumento</th><th>Puntaje</th></tr></thead><tbody>${rows}</tbody></table><div class="paperBar" style="margin-top:10px">Última corrección</div><div class="paperInfo"><div class="line"><b>Correcciones</b><span>${db.corrections.length}</span></div><div class="line"><b>Feedback</b><span>Disponible por OA</span></div></div>`,7,'left')}${paper(`<div class="bookTitle">Observaciones y seguimiento</div><table class="paperTable"><thead><tr><th>Estudiante</th><th>Señal</th><th>Acción</th></tr></thead><tbody><tr><td>Camila Flores</td><td>Comprensión lectora</td><td>Refuerzo + seguimiento UTP</td></tr><tr><td>Francisco Díaz</td><td>Puntualidad</td><td>Acuerdo con apoderado</td></tr><tr><td>Renato Vega</td><td>RFID baja confianza</td><td>Validación docente</td></tr></tbody></table><div class="paperBar" style="margin-top:10px">Evidencia</div><div class="paperInfo"><div class="line"><b>Auditoría</b><span>${db.audit.length} eventos</span></div><div class="line"><b>Portabilidad</b><span>Exportable</span></div></div>`,8,'right')}</div>`}

function plannerPage(){const days=['Lunes','Martes','Miércoles','Jueves','Viernes'];return `<div class="page"><div class="pageHead"><div><h1>Planificador pedagógico</h1><p>Planifica desde el OA y reutiliza el mismo contexto en evaluaciones, recursos y leccionario.</p></div><div class="actions"><button class="btn blue" onclick="openPlanModal()">+ Nueva planificación</button><button class="btn" onclick="go('curriculum')">Buscar OA</button></div></div><div class="week">${days.map(d=>`<div class="day"><h4>${d}</h4>${db.plans.filter(p=>p.day===d).map(p=>`<div class="planCard ${p.subject.includes('Lengua')?'red':p.subject.includes('Ciencias')?'green':''}"><b>${p.time} · ${p.subject}</b><small>${p.oa}<br>${p.title}<br><b>Evidencia:</b> ${p.evidence}</small></div>`).join('')||'<div class="subtle">Sin clases planificadas</div>'}</div>`).join('')}</div><div class="grid cols2" style="margin-top:15px"><div class="card"><div class="cardHead"><h3>Diseño de clase seleccionado</h3><span class="badge blue">${selectedOA?selectedOA.code:'Sin OA'}</span></div>${selectedOA?`<p style="font-size:12px;line-height:1.55"><b>${selectedOA.subject}</b> · ${selectedOA.unit}<br>${selectedOA.text}</p><div class="list"><div class="row"><div class="rowText"><b>Inicio · 10 min</b><small>Activar conocimientos previos con pregunta problemática.</small></div></div><div class="row"><div class="rowText"><b>Desarrollo · 55 min</b><small>Modelado docente + trabajo colaborativo + andamiaje.</small></div></div><div class="row"><div class="rowText"><b>Cierre · 15 min</b><small>Ticket de salida y metacognición breve.</small></div></div></div>`:'Selecciona un OA.'}</div><div class="card"><div class="cardHead"><h3>Diferenciación y apoyos</h3><span class="badge ok">UDL</span></div><div class="row"><div class="rowText"><b>Múltiples formas de representación</b><small>Ejemplos visuales, tabla, gráfico y explicación oral.</small></div></div><div class="row"><div class="rowText"><b>Múltiples formas de acción</b><small>Respuesta escrita, oral o mediante organizador.</small></div></div><div class="row"><div class="rowText"><b>Monitoreo formativo</b><small>Semáforo de comprensión + ticket de salida.</small></div></div></div></div></div>`}
function openPlanModal(){const oa=selectedOA||CURRICULUM[0];modal(`<div class="modalHead"><div><span class="eyebrow">Nueva planificación</span><h2>Planificar desde OA</h2></div><button class="close" onclick="closeModal()">×</button></div><label>Día</label><select id="plDay" class="field"><option>Lunes</option><option>Martes</option><option>Miércoles</option><option>Jueves</option><option>Viernes</option></select><div class="grid equal2"><div><label>Hora</label><input id="plTime" class="field" value="08:30"></div><div><label>Asignatura</label><input id="plSubject" class="field" value="${esc(oa.subject)}"></div></div><label>OA</label><input id="plOA" class="field" value="${esc(oa.code)}"><label>Foco / título</label><input id="plTitle" class="field" value="Clase vinculada a ${esc(oa.unit)}"><label>Evidencia de aprendizaje</label><input id="plEvidence" class="field" value="Ticket de salida"><button class="btn primary" style="margin-top:14px" onclick="savePlan()">Guardar y vincular al Libro</button>`)}
function savePlan(){db.plans.push({day:val('plDay'),time:val('plTime'),subject:val('plSubject'),oa:val('plOA'),title:val('plTitle'),evidence:val('plEvidence')});db.audit.push({time:now(),actor:db.user.name,event:'Planificación creada',detail:`${val('plSubject')} · ${val('plOA')}`});save();closeModal();render();}

function curriculumPage(){const levels=[...new Set(CURRICULUM.map(x=>x.level))],subjects=[...new Set(CURRICULUM.map(x=>x.subject))];const level=window.currLevel||'2° Medio',subject=window.currSubject||'Todas';const data=CURRICULUM.filter(x=>x.level===level&&(subject==='Todas'||x.subject===subject));return `<div class="page"><div class="pageHead"><div><h1>Currículum y Objetivos de Aprendizaje</h1><p>Un hub curricular para que el docente no tenga que buscar OA en múltiples documentos. En esta DEMO se incluyen ejemplos representativos y el modelo de datos para cargar el catálogo oficial completo.</p></div><div class="actions"><span class="badge warn">Catálogo parcial DEMO</span><button class="btn" onclick="showCurriculumArchitecture()">Ver arquitectura de carga</button></div></div><div class="sourceStrip"><b>Fuente de referencia:</b> Currículum Nacional del Ministerio de Educación. Los textos mostrados aquí son resúmenes de demostración para validar UX, no transcripciones oficiales completas. La versión productiva debe importar, versionar y citar cada OA desde la fuente oficial vigente.</div><div class="toolbar" style="margin-top:12px"><select class="field" onchange="window.currLevel=this.value;render()">${levels.map(x=>`<option ${x===level?'selected':''}>${x}</option>`).join('')}</select><select class="field" onchange="window.currSubject=this.value;render()"><option>Todas</option>${subjects.map(x=>`<option ${x===subject?'selected':''}>${x}</option>`).join('')}</select><input class="field search" placeholder="Buscar OA, unidad o habilidad" oninput="filterOA(this.value)"></div><div id="oaList">${data.map(oa=>oaCard(oa)).join('')}</div></div>`}
function oaCard(oa){const idx=CURRICULUM.indexOf(oa);return `<article class="oaCard" data-oa="${esc((oa.code+' '+oa.text+' '+oa.unit+' '+oa.subject).toLowerCase())}"><div class="oaCode">${oa.code}</div><h4>${oa.subject} · ${oa.unit}</h4><p>${oa.text}</p><div style="margin-top:7px">${oa.skills.map(s=>`<span class="badge">${s}</span>`).join(' ')}</div><div class="oaActions"><button class="btn tiny blue" onclick="selectOA(${idx},'planificador')">Usar en planificación</button><button class="btn tiny" onclick="selectOA(${idx},'evaluaciones')">Crear evaluación</button><button class="btn tiny" onclick="selectOA(${idx},'recursos')">Buscar recursos</button></div><div class="subtle" style="margin-top:8px">${oa.source}</div></article>`}
function filterOA(q){q=q.toLowerCase();document.querySelectorAll('.oaCard').forEach(el=>el.style.display=el.dataset.oa.includes(q)?'block':'none');}
function selectOA(i,target){selectedOA=CURRICULUM[i];route=target;render();}
function showCurriculumArchitecture(){modal(`<div class="modalHead"><div><span class="eyebrow">Arquitectura curricular</span><h2>Cómo cargar el catálogo oficial completo</h2></div><button class="close" onclick="closeModal()">×</button></div><p class="muted">La DEMO ya trabaja con el esquema que usaría una importación masiva del Currículum Nacional:</p><div class="tableWrap"><table><thead><tr><th>Campo</th><th>Uso</th></tr></thead><tbody><tr><td>nivel</td><td>Curso o nivel</td></tr><tr><td>asignatura</td><td>Área curricular</td></tr><tr><td>oa_code</td><td>Código oficial/versionado</td></tr><tr><td>oa_statement</td><td>Texto oficial del OA</td></tr><tr><td>habilidades</td><td>Habilidades/actitudes asociadas</td></tr><tr><td>indicadores</td><td>Indicadores de evaluación</td></tr><tr><td>unidad</td><td>Unidad o eje</td></tr><tr><td>source_url</td><td>Fuente oficial</td></tr><tr><td>version</td><td>Versión curricular vigente</td></tr></tbody></table></div><p style="font-size:11px">El paso productivo es construir un importador/ETL que ingiera y versiona la fuente oficial, no copiar manualmente los OA dentro del frontend.</p>`)}

function evaluationPage(){const oa=selectedOA||CURRICULUM[1];return `<div class="page"><div class="pageHead"><div><h1>Creador de instrumentos</h1><p>Genera una evaluación desde el mismo OA seleccionado en Currículum o Planificador. En la DEMO el generador es determinístico; en producción puede conectarse a un orquestador de IA con validación docente.</p></div><div class="actions"><button class="btn" onclick="go('curriculum')">Cambiar OA</button><button class="btn blue" onclick="generateInstrument()">Generar instrumento</button></div></div><div class="grid cols2"><div class="card"><div class="cardHead"><h3>Configuración</h3><span class="badge blue">${oa.code}</span></div><label>Asignatura</label><input id="evSubject" class="field" value="${esc(oa.subject)}"><label>OA / foco curricular</label><textarea id="evOA" class="field" style="min-height:82px">${esc(oa.text)}</textarea><div class="grid equal2"><div><label>Tipo</label><select id="evType" class="field"><option>Mixto</option><option>Selección múltiple</option><option>Desarrollo</option><option>Rúbrica de desempeño</option></select></div><div><label>N° preguntas</label><select id="evCount" class="field"><option>5</option><option>8</option><option>10</option></select></div></div><div class="grid equal2"><div><label>Dificultad</label><select id="evDifficulty" class="field"><option>Progresiva</option><option>Básica</option><option>Intermedia</option><option>Desafiante</option></select></div><div><label>Puntaje total</label><input id="evPoints" class="field" value="20"></div></div></div><div class="card"><div class="cardHead"><h3>Instrumentos guardados</h3><span class="badge ok">${db.instruments.length}</span></div><div class="list">${db.instruments.map(x=>`<div class="row"><div class="rowMain"><div class="rowIcon">🧪</div><div class="rowText"><b>${x.name}</b><small>${x.subject} · ${x.oa} · ${x.questions.length} preguntas</small></div></div><button class="btn tiny" onclick="previewInstrument(${x.id})">Ver</button></div>`).join('')}</div></div></div><div id="instrumentPreview" style="margin-top:15px"></div></div>`}
function generateInstrument(){const subject=val('evSubject'),oa=selectedOA||CURRICULUM.find(x=>x.subject===subject)||CURRICULUM[0],count=Number(val('evCount')||5);const bank=[
 {type:'mc',text:`¿Cuál de las siguientes situaciones representa mejor el foco trabajado en ${oa.unit}?`,options:['Aplicar el concepto en un caso contextualizado','Memorizar una definición sin usarla','Copiar un ejemplo sin analizarlo','Evitar justificar la respuesta'],answer:0,points:2},
 {type:'mc',text:`¿Qué evidencia mostraría un logro adecuado del objetivo ${oa.code}?`,options:['Explicar y aplicar el aprendizaje con evidencia','Responder al azar','Repetir palabras clave sin relación','Omitir el procedimiento'],answer:0,points:2},
 {type:'open',text:`Explica con tus palabras el aprendizaje central de ${oa.unit} y entrega un ejemplo.`,keywords:['explica','ejemplo','aplica','evidencia'],points:4},
 {type:'open',text:`Resuelve o analiza una situación nueva vinculada a: ${oa.text}`,keywords:['procedimiento','justifica','resultado','evidencia'],points:4},
 {type:'mc',text:'¿Qué estrategia ayuda más a verificar una respuesta?',options:['Comprobar el procedimiento y contrastar con evidencia','Entregar sin revisar','Eliminar datos relevantes','Cambiar la respuesta al azar'],answer:0,points:2},
 {type:'open',text:'¿Qué error frecuente podría ocurrir y cómo lo corregirías?',keywords:['error','corregir','revisar'],points:3},
 {type:'mc',text:'¿Cuál es la mejor forma de comunicar una conclusión?',options:['Con evidencia y lenguaje disciplinar pertinente','Sin explicar el razonamiento','Solo con una palabra','Copiando la pregunta'],answer:0,points:2},
 {type:'open',text:'Crea una pregunta propia que permita demostrar el OA seleccionado.',keywords:['pregunta','demostrar','objetivo'],points:3},
 {type:'mc',text:'¿Qué criterio permite distinguir una respuesta de mayor calidad?',options:['Coherencia, evidencia y procedimiento','Extensión sin relación','Uso de palabras difíciles','Rapidez únicamente'],answer:0,points:2},
 {type:'open',text:'Redacta una breve reflexión sobre qué te resultó más desafiante y por qué.',keywords:['desafiante','porque','aprendí'],points:2}
 ];const qs=bank.slice(0,count);const inst={id:Date.now(),name:`${subject} · ${oa.unit} · ${new Date().toLocaleDateString('es-CL')}`,subject,oa:oa.code,questions:qs};db.instruments.push(inst);db.audit.push({time:now(),actor:db.user.name,event:'Instrumento creado',detail:`${subject} · ${oa.code}`});save();render();setTimeout(()=>previewInstrument(inst.id),0);}
function previewInstrument(id){const x=db.instruments.find(i=>i.id===id);if(!x)return;const html=`<div class="card"><div class="cardHead"><div><h3>${esc(x.name)}</h3><div class="subtle">${x.oa} · ${x.questions.reduce((a,q)=>a+q.points,0)} puntos</div></div><div class="actions"><button class="btn small" onclick="window.print()">Imprimir</button><button class="btn small blue" onclick="route='corrector';window.correctInstrument=${x.id};render()">Enviar a corrector</button></div></div>${x.questions.map((q,i)=>`<div class="question"><div class="qnum">PREGUNTA ${i+1} · ${q.points} pts</div><h4>${q.text}</h4>${q.type==='mc'?q.options.map((o,j)=>`<div class="option"><span>○</span><span>${String.fromCharCode(65+j)}. ${o}</span></div>`).join(''):'<div style="height:55px;border-bottom:1px solid #dbe4eb;background:repeating-linear-gradient(#fff 0 24px,#e8eef3 25px)"></div>'}</div>`).join('')}</div>`;document.getElementById('instrumentPreview').innerHTML=html;document.getElementById('instrumentPreview').scrollIntoView({behavior:'smooth'});}

function correctorPage(){const instruments=db.instruments;const id=window.correctInstrument||instruments[0]?.id;const inst=instruments.find(x=>x.id===Number(id))||instruments[0];return `<div class="page"><div class="pageHead"><div><h1>Corrector de instrumentos</h1><p>Corrección asistida: selección múltiple exacta + evaluación demostrativa de respuestas abiertas por criterios. El docente conserva la validación final.</p></div></div><div class="grid cols2"><div class="card"><div class="cardHead"><h3>Respuesta a corregir</h3><span class="badge warn">Human-in-the-loop</span></div><label>Instrumento</label><select id="corrInst" class="field" onchange="window.correctInstrument=this.value;render()">${instruments.map(x=>`<option value="${x.id}" ${inst&&x.id===inst.id?'selected':''}>${x.name}</option>`).join('')}</select><label>Estudiante</label><select id="corrStudent" class="field">${db.students.map(s=>`<option>${s.name}</option>`).join('')}</select><label>Respuestas (DEMO)</label><textarea id="corrAnswers" class="field" style="min-height:180px">1:A
2:A
3:Explico el concepto, muestro un ejemplo y justifico con evidencia.
4:Describo el procedimiento, reviso el resultado y justifico la respuesta.
5:A</textarea><button class="btn green" style="margin-top:12px" onclick="runCorrection()">Corregir y generar feedback</button></div><div class="card" id="corrResult"><div class="empty">Ejecuta una corrección para ver puntaje, feedback y brechas por OA.</div></div></div><div class="card" style="margin-top:15px"><div class="cardHead"><h3>Historial de correcciones</h3><span class="badge">${db.corrections.length}</span></div>${db.corrections.length?`<div class="tableWrap"><table><thead><tr><th>Fecha</th><th>Estudiante</th><th>Instrumento</th><th>Puntaje</th><th>%</th></tr></thead><tbody>${db.corrections.slice().reverse().map(c=>`<tr><td>${c.time}</td><td>${c.student}</td><td>${c.instrument}</td><td>${c.score}/${c.total}</td><td>${c.percent}%</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Sin correcciones guardadas.</div>'}</div></div>`}
function runCorrection(){const inst=db.instruments.find(x=>x.id===Number(val('corrInst')));if(!inst)return alert('Crea primero un instrumento.');const lines=val('corrAnswers').split('\n').map(x=>x.trim()).filter(Boolean);let score=0,total=0,openFeedback=[];inst.questions.forEach((q,i)=>{total+=q.points;const line=lines.find(x=>x.startsWith(`${i+1}:`))||'';const ans=line.split(':').slice(1).join(':').trim();if(q.type==='mc'){const letter=String.fromCharCode(65+q.answer);if(ans.toUpperCase().startsWith(letter))score+=q.points;}else{const hits=(q.keywords||[]).filter(k=>ans.toLowerCase().includes(k.toLowerCase())).length;const p=Math.round(q.points*Math.min(1,hits/Math.max(2,(q.keywords||[]).length)));score+=p;openFeedback.push(`${i+1}. ${p}/${q.points} pts · ${hits?'Incluye elementos del criterio.':'Requiere mayor evidencia y explicación.'}`);}});const percent=Math.round(score/total*100),student=val('corrStudent');db.corrections.push({time:now(),student,instrument:inst.name,score,total,percent,oa:inst.oa});db.audit.push({time:now(),actor:db.user.name,event:'Instrumento corregido',detail:`${student} · ${percent}% · ${inst.oa}`});save();document.getElementById('corrResult').innerHTML=`<div class="cardHead"><h3>Resultado</h3><span class="badge ${percent>=60?'ok':'red'}">${percent>=60?'Logro esperado':'Requiere apoyo'}</span></div><div class="corrScore">${percent}%</div><div class="subtle">${score} de ${total} puntos · ${inst.oa}</div><div class="feedback" style="margin-top:13px"><b>Retroalimentación sugerida</b><br>${percent>=80?'Buen dominio. Avanzar a tareas de aplicación y transferencia.':percent>=60?'Se observa logro parcial. Reforzar procedimientos y justificación con evidencia.':'Priorizar reenseñanza guiada y práctica con andamiaje.'}</div><div class="feedback" style="margin-top:8px">${openFeedback.join('<br>')}</div><button class="btn small blue" style="margin-top:10px" onclick="go('estudiantes')">Ver en Student 360</button>`;}

function resourcesPage(){const oa=selectedOA;const filtered=oa?db.resources.filter(r=>r.oa===oa.code||r.subject===oa.subject):db.resources;return `<div class="page"><div class="pageHead"><div><h1>Biblioteca pedagógica</h1><p>Actividades, guías, presentaciones, material didáctico y videos organizados por nivel, asignatura y OA.</p></div><div class="actions"><button class="btn" onclick="go('curriculum')">Seleccionar OA</button><button class="btn blue" onclick="createResource()">+ Crear recurso desde OA</button></div></div>${oa?`<div class="sourceStrip"><b>Filtro activo:</b> ${oa.code} · ${oa.subject} · ${oa.unit}</div>`:''}<div class="toolbar" style="margin-top:12px"><input id="resSearch" class="field search" placeholder="Buscar recurso" oninput="filterResources(this.value)"><select id="resType" class="field" onchange="filterResources(document.getElementById('resSearch').value)"><option>Todos</option><option>Actividad</option><option>Guía</option><option>Presentación</option><option>Video</option><option>Material didáctico</option><option>Juego</option></select></div><div id="resourceGrid" class="resourceGrid">${filtered.map(resourceCard).join('')}</div></div>`}
function resourceCard(r){const cls=r.type==='Video'?'video':r.type==='Presentación'?'presentation':r.type==='Material didáctico'?'didactic':'';return `<article class="resource" data-r="${esc((r.title+' '+r.subject+' '+r.type+' '+r.desc).toLowerCase())}" data-type="${r.type}"><div class="resourceThumb ${cls}">${r.icon}</div><div class="resourceBody"><h4>${r.title}</h4><p>${r.desc}</p><div class="resourceMeta"><span class="badge">${r.type}</span><span class="badge blue">${r.subject}</span></div><button class="btn tiny" onclick="openResource(${r.id})">Abrir</button> <button class="btn tiny blue" onclick="useResource(${r.id})">Usar en clase</button></div></article>`}
function filterResources(q){q=(q||'').toLowerCase();const type=document.getElementById('resType')?.value||'Todos';document.querySelectorAll('.resource').forEach(el=>el.style.display=(el.dataset.r.includes(q)&&(type==='Todos'||el.dataset.type===type))?'block':'none');}
function openResource(id){const r=db.resources.find(x=>x.id===id);modal(`<div class="modalHead"><div><span class="eyebrow">${r.type}</span><h2>${r.title}</h2></div><button class="close" onclick="closeModal()">×</button></div><p>${r.desc}</p><div class="sourceStrip"><b>OA asociado:</b> ${r.oa}<br><b>Asignatura:</b> ${r.subject} · ${r.level}</div><div style="margin-top:12px" class="feedback"><b>Secuencia sugerida</b><br>1. Activación breve.<br>2. Modelado o demostración.<br>3. Trabajo guiado/colaborativo.<br>4. Evidencia de aprendizaje.<br>5. Cierre y retroalimentación.</div><div class="actions" style="margin-top:12px"><button class="btn blue" onclick="useResource(${r.id});closeModal()">Agregar a planificación</button><button class="btn" onclick="window.print()">Imprimir ficha</button></div>`)}
function useResource(id){const r=db.resources.find(x=>x.id===id);const oa=CURRICULUM.find(x=>x.code===r.oa);if(oa)selectedOA=oa;db.plans.push({day:'Viernes',time:'12:00',subject:r.subject,oa:r.oa,title:r.title,evidence:`Producto usando recurso ${r.type}`});db.audit.push({time:now(),actor:db.user.name,event:'Recurso vinculado',detail:`${r.title} → planificación`});save();route='planificador';render();}
function createResource(){const oa=selectedOA||CURRICULUM[0];const id=Date.now();db.resources.push({id,subject:oa.subject,level:oa.level,type:'Actividad',icon:'✨',title:`Actividad desde ${oa.code}`,desc:`Actividad generada en DEMO para trabajar ${oa.unit} con inicio, desafío central y cierre.`,oa:oa.code});save();render();}

function rfidPage(){const exceptions=db.students.filter(s=>s.today!=='Presente');return `<div class="page"><div class="pageHead"><div><h1>Presence Engine · RFID UHF</h1><p>Dos niveles de evidencia: ingreso al establecimiento + ingreso a sala. La lectura física es un evento; el estado oficial se valida por reglas y, cuando corresponde, por una persona.</p></div><div class="actions"><button class="btn blue" onclick="runRFID()">▶ Simular ingreso de 30 estudiantes</button><button class="btn green" onclick="signAttendance()">Firmar asistencia</button></div></div><div class="portalWrap"><div class="card"><div class="portalStage" id="portalStage"><div class="scanPanel"><b id="scanName">Portal listo</b><small id="scanMeta">Esperando simulación</small></div><div class="ground"></div><div class="gate one"><span class="gateLabel">Portal establecimiento</span></div><div class="gate two"><span class="gateLabel">Portal sala 2°B</span></div>${db.students.map((s,i)=>`<div class="walker" style="--delay:${i*.1}s"></div>`).join('')}</div><div class="rfidMetrics"><div class="rfidMetric"><small>Detectados</small><b id="rfidCount">30</b></div><div class="rfidMetric"><small>Resueltos</small><b id="rfidResolved">28</b></div><div class="rfidMetric"><small>Excepciones</small><b id="rfidExc">${exceptions.length}</b></div></div></div><div class="card"><div class="cardHead"><h3>Excepciones para revisión humana</h3><span class="badge warn">${exceptions.length}</span></div>${exceptions.map(s=>`<div class="exception"><b>${s.name}</b><small>Propuesta: ${s.today} · confianza ${s.confidence}%</small><div class="actions"><button class="btn tiny green" onclick="resolveAttendance(${s.id},'Presente')">Presente</button><button class="btn tiny" onclick="resolveAttendance(${s.id},'Atrasado')">Atrasado</button><button class="btn tiny" onclick="resolveAttendance(${s.id},'Ausente')">Ausente</button></div></div>`).join('')||'<div class="empty">No quedan excepciones.</div>'}<div class="feedback"><b>Estado oficial</b><br>${db.attendanceSigned?'Asistencia firmada y cerrada.':'Pendiente de firma.'}</div></div></div></div>`}
function runRFID(){const st=document.getElementById('portalStage');st.classList.remove('running');void st.offsetWidth;st.classList.add('running');let i=0;const timer=setInterval(()=>{i++;const s=db.students[i-1];if(s){document.getElementById('scanName').textContent=`${String(s.id).padStart(2,'0')} · ${s.name}`;document.getElementById('scanMeta').textContent=`Confianza ${s.confidence}% · ${s.today}`;document.getElementById('rfidCount').textContent=i;document.getElementById('rfidResolved').textContent=Math.min(i,28);document.getElementById('rfidExc').textContent=i<6?0:i<30?1:2;}if(i>=30){clearInterval(timer);db.audit.push({time:now(),actor:'Presence Engine',event:'Asistencia propuesta',detail:'28 presentes · 1 atraso · 1 lectura pendiente'});save();}},120);}
function resolveAttendance(id,state){const s=db.students.find(x=>x.id===id);const before=s.today;s.today=state;s.confidence=100;db.audit.push({time:now(),actor:db.user.name,event:'Asistencia validada',detail:`${s.name}: ${before} → ${state}`});save();render();}
function signAttendance(){if(db.students.some(s=>s.today==='Pendiente'))return alert('Primero resuelve la lectura pendiente.');db.attendanceSigned=true;db.audit.push({time:now(),actor:db.user.name,event:'Asistencia firmada',detail:`${db.school.course} · 30 registros`});save();render();}

function withdrawalPage(){return `<div class="page"><div class="pageHead"><div><h1>Registro de retiro de estudiantes</h1><p>Inspectoría registra quién retira, verifica autorización, motivo, hora, firma y deja trazabilidad. El módulo evita planillas paralelas.</p></div><div class="actions"><button class="btn blue" onclick="openWithdrawal()">+ Registrar retiro</button></div></div><div class="grid cols2"><div class="card"><div class="cardHead"><h3>Retiros recientes</h3><span class="badge">${db.withdrawals.length}</span></div><div class="tableWrap"><table><thead><tr><th>Fecha/hora</th><th>Estudiante</th><th>Retira</th><th>Motivo</th><th>Estado</th></tr></thead><tbody>${db.withdrawals.slice().reverse().map(w=>`<tr><td>${w.time}</td><td>${w.student}</td><td>${w.pickup}<br><span class="subtle">${w.relation}</span></td><td>${w.reason}</td><td><span class="pill green">${w.status}</span></td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="cardHead"><h3>Protocolo digital</h3><span class="badge ok">Auditable</span></div><div class="list"><div class="row"><div class="rowIcon">1</div><div class="rowText"><b>Identificar estudiante</b><small>Curso + estudiante + apoderado</small></div></div><div class="row"><div class="rowIcon">2</div><div class="rowText"><b>Verificar persona autorizada</b><small>Relación, identificación y autorización</small></div></div><div class="row"><div class="rowIcon">3</div><div class="rowText"><b>Registrar motivo y hora</b><small>Salida trazable</small></div></div><div class="row"><div class="rowIcon">4</div><div class="rowText"><b>Firma + notificación</b><small>Firma de quien retira y aviso a familia/curso</small></div></div></div></div></div></div>`}
function openWithdrawal(){modal(`<div class="modalHead"><div><span class="eyebrow">Inspectoría</span><h2>Registrar retiro</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="withdrawForm"><div><label>Estudiante</label><select id="wdStudent" class="field" onchange="prefillGuardian()">${db.students.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></div><div><label>Hora</label><input id="wdTime" class="field" type="time" value="${new Date().toTimeString().slice(0,5)}"></div><div><label>Persona que retira</label><input id="wdPickup" class="field" value="${db.students[0].guardian}"></div><div><label>Relación</label><select id="wdRel" class="field"><option>Madre</option><option>Padre</option><option>Apoderado/a</option><option>Adulto autorizado</option></select></div></div><label>Motivo</label><input id="wdReason" class="field" value="Control médico"><label><input id="wdVerified" type="checkbox" checked> Persona verificada/autorizada</label><label>Firma (demo)</label><input id="wdSig" class="field" value="Firma digital demo"><div class="sigbox">Firma digital / manuscrita capturada</div><button class="btn primary" style="margin-top:12px" onclick="saveWithdrawal()">Confirmar retiro</button>`)}
function prefillGuardian(){const s=db.students.find(x=>x.id===Number(val('wdStudent')));if(s)document.getElementById('wdPickup').value=s.guardian;}
function saveWithdrawal(){const s=db.students.find(x=>x.id===Number(val('wdStudent'))),verified=document.getElementById('wdVerified').checked;if(!verified&&!confirm('La persona no está marcada como verificada. ¿Registrar igualmente en modo DEMO?'))return;db.withdrawals.push({id:Date.now(),time:`${new Date().toLocaleDateString('es-CL')} ${val('wdTime')}`,student:s.name,pickup:val('wdPickup'),relation:val('wdRel'),reason:val('wdReason'),verified,status:'Retirado',signature:val('wdSig')});db.audit.push({time:now(),actor:db.user.name,event:'Retiro registrado',detail:`${s.name} · ${val('wdPickup')} · ${val('wdReason')}`});save();closeModal();render();}

function studentsPage(){const s=db.students[0];const corr=db.corrections.filter(c=>c.student===s.name);return `<div class="page"><div class="pageHead"><div><h1>Student 360</h1><p>Vista longitudinal autorizada: asistencia, evaluaciones, planificación de apoyo, observaciones y retiros. La información se muestra según perfil y finalidad.</p></div></div><div class="grid cols3"><div class="card"><div class="cardHead"><h3>${s.name}</h3><span class="badge blue">${s.course}</span></div><div class="avatar" style="width:60px;height:60px;font-size:18px">${initials(s.name)}</div><p style="font-size:12px"><b>RUN/IPE:</b> ${s.run}<br><b>Apoderado:</b> ${s.guardian}<br><b>Contacto:</b> ${s.phone}</p><div class="feedback"><b>Privacidad:</b> vista de demostración. En producción se aplica mínimo privilegio y registro de accesos.</div></div><div class="card"><div class="cardHead"><h3>Indicadores</h3></div><div class="grid equal2"><div class="stat"><div class="num">96%</div><div class="label">asistencia</div></div><div class="stat"><div class="num">5,8</div><div class="label">promedio demo</div></div><div class="stat"><div class="num">0</div><div class="label">alertas críticas</div></div><div class="stat"><div class="num">${corr.length}</div><div class="label">correcciones</div></div></div></div><div class="card"><div class="cardHead"><h3>Trayectoria reciente</h3></div><div class="timeline"><div class="event"><b>Asistencia</b><br><small>Presente · fuente RFID</small></div><div class="event"><b>Planificación</b><br><small>Participa en Matemática · funciones</small></div><div class="event"><b>Evaluación</b><br><small>Feedback disponible por OA</small></div><div class="event"><b>Familia</b><br><small>Contacto verificado</small></div></div></div></div><div class="card" style="margin-top:15px"><div class="cardHead"><h3>Nómina rápida</h3><span class="badge">30 estudiantes</span></div><div class="tableWrap"><table><thead><tr><th>Estudiante</th><th>Asistencia hoy</th><th>Confianza</th><th>Apoderado</th></tr></thead><tbody>${db.students.map(x=>`<tr><td>${x.name}</td><td>${x.today}</td><td>${x.confidence}%</td><td>${x.guardian}</td></tr>`).join('')}</tbody></table></div></div></div>`}

function communityPage(){return `<div class="page"><div class="pageHead"><div><h1>Comunidad educativa</h1><p>Comunicación segmentada, autorizaciones y acceso por perfil para familias, docentes, asistentes, equipos PIE/convivencia y sostenedor.</p></div><div class="actions"><button class="btn blue" onclick="composeMessage()">+ Nuevo aviso</button></div></div><div class="grid cols3"><div class="card"><div class="cardHead"><h3>Familias</h3><span class="badge ok">30 activas</span></div><p class="subtle">Asistencia, avisos, autorizaciones y comunicaciones sin exponer información innecesaria.</p><div class="list"><div class="row"><div class="rowText"><b>Autorización salida pedagógica</b><small>24/30 respondidas</small></div><span class="pill amber">6 pendientes</span></div><div class="row"><div class="rowText"><b>Reunión de apoderados</b><small>Martes 19:00</small></div><span class="pill green">enviado</span></div></div></div><div class="card"><div class="cardHead"><h3>Equipo educativo</h3></div><div class="row"><div class="rowIcon">👩‍🏫</div><div class="rowText"><b>Docentes</b><small>12 usuarios activos</small></div></div><div class="row"><div class="rowIcon">🧑‍💼</div><div class="rowText"><b>Asistentes</b><small>8 usuarios activos</small></div></div><div class="row"><div class="rowIcon">🧠</div><div class="rowText"><b>PIE / apoyo</b><small>4 perfiles restringidos</small></div></div></div><div class="card"><div class="cardHead"><h3>Próximos hitos</h3></div><div class="timeline"><div class="event"><b>Consejo de profesores</b><br><small>Miércoles · 16:30</small></div><div class="event"><b>Reunión apoderados</b><br><small>Jueves · 19:00</small></div><div class="event"><b>Salida pedagógica</b><br><small>Viernes · autorizaciones</small></div></div></div></div></div>`}
function composeMessage(){modal(`<div class="modalHead"><div><span class="eyebrow">Comunicación</span><h2>Nuevo aviso</h2></div><button class="close" onclick="closeModal()">×</button></div><label>Destinatarios</label><select class="field"><option>Apoderados 2° Medio B</option><option>Docentes del curso</option><option>Equipo directivo</option></select><label>Asunto</label><input class="field" value="Información importante del curso"><label>Mensaje</label><textarea class="field" style="min-height:140px">Estimadas familias: informamos que...</textarea><button class="btn blue" style="margin-top:12px" onclick="alert('Aviso enviado en modo DEMO');closeModal()">Enviar DEMO</button>`)}

function reportsPage(){return `<div class="page"><div class="pageHead"><div><h1>Control Tower · Dirección / DAEM / SLEP</h1><p>No es un dashboard decorativo: prioriza excepciones, cumplimiento, adopción y acciones pendientes.</p></div><div class="actions"><button class="btn" onclick="exportAudit()">Exportar auditoría</button></div></div><div class="grid cols4"><div class="card stat accentBlue"><div class="statIcon">🏫</div><div class="num">6</div><div class="label">establecimientos DEMO</div></div><div class="card stat accentGreen"><div class="statIcon">✅</div><div class="num">98%</div><div class="label">clases firmadas</div></div><div class="card stat accentRed"><div class="statIcon">⚠️</div><div class="num">3</div><div class="label">incidencias críticas</div></div><div class="card stat accentViolet"><div class="statIcon">📚</div><div class="num">91%</div><div class="label">cobertura OA</div></div></div><div class="grid cols2" style="margin-top:15px"><div class="card"><div class="cardHead"><h3>Asistencia por establecimiento</h3></div><div class="barChart">${[94,92,96,88,95,93].map((v,i)=>`<div class="bar ${v<90?'red':i===2?'highlight':''}" style="height:${v}%"><span>${v}%</span><small>E${i+1}</small></div>`).join('')}</div></div><div class="card"><div class="cardHead"><h3>Qué requiere atención hoy</h3><span class="badge red">prioridad</span></div><div class="list"><div class="row"><div class="rowText"><b>1 establecimiento bajo 90% asistencia</b><small>Revisar tendencia semanal</small></div><span class="pill red">Alta</span></div><div class="row"><div class="rowText"><b>17 diferencias de conciliación</b><small>Cola EDE/SIGE DEMO</small></div><span class="pill amber">Media</span></div><div class="row"><div class="rowText"><b>3 clases sin firma >24h</b><small>Notificar responsables</small></div><span class="pill amber">Media</span></div><div class="row"><div class="rowText"><b>1 lectura de datos sensible inusual</b><small>Revisión de auditoría</small></div><span class="pill red">Alta</span></div></div></div></div><div class="card" style="margin-top:15px"><div class="cardHead"><h3>Auditoría reciente</h3><span class="badge">${db.audit.length} eventos</span></div><div class="tableWrap"><table><thead><tr><th>Fecha/hora</th><th>Actor</th><th>Evento</th><th>Detalle</th></tr></thead><tbody>${db.audit.slice().reverse().map(a=>`<tr><td>${a.time}</td><td>${a.actor}</td><td>${a.event}</td><td>${a.detail}</td></tr>`).join('')}</tbody></table></div></div></div>`}

function modal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modal').classList.remove('hidden');}
function closeModal(){document.getElementById('modal').classList.add('hidden');}
function val(id){return document.getElementById(id)?.value||'';}
function exportAudit(){const blob=new Blob([JSON.stringify({demo:true,school:db.school,audit:db.audit,withdrawals:db.withdrawals,corrections:db.corrections},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ecosistema3-auditoria-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function resetDemo(){if(!confirm('¿Reiniciar toda la DEMO?'))return;const user=db.user;db=structuredClone(initialDB);db.user=user;selectedOA=CURRICULUM[1];bookSpread=0;save();route='inicio';render();}

const PRES=[
 {route:'inicio',title:'1. El salto: de libro digital a ecosistema',script:'Muestre que el Libro 3.0 sigue siendo el núcleo, pero se conecta con planificación, currículum, evaluación, recursos, RFID, familias y gestión.'},
 {route:'curriculum',title:'2. Currículum y OA como fuente única',script:'Seleccione un OA. Explique que el mismo objetivo alimenta planificación, recursos, evaluación y trazabilidad. La DEMO usa ejemplos y deja listo el modelo para carga oficial completa.'},
 {route:'planificador',title:'3. Planificar sin volver a escribir',script:'Muestre la semana y cómo el OA elegido se reutiliza en una secuencia con inicio, desarrollo, cierre y evidencia.'},
 {route:'recursos',title:'4. Biblioteca pedagógica',script:'Muestre actividades, guías, presentaciones, material didáctico y videos filtrados por OA. Agregue un recurso a planificación.'},
 {route:'evaluaciones',title:'5. Crear instrumento desde el OA',script:'Genere una evaluación. Destaque que el docente configura y valida; la automatización reduce tiempo, no reemplaza criterio profesional.'},
 {route:'corrector',title:'6. Corregir y retroalimentar',script:'Ejecute la corrección DEMO y muestre puntaje, feedback y brechas vinculadas al mismo OA.'},
 {route:'rfid',title:'7. Automatizar asistencia',script:'Simule los 30 ingresos. El sistema resuelve casos normales y entrega solo excepciones a revisión humana.'},
 {route:'retiros',title:'8. Registrar retiros con trazabilidad',script:'Muestre autorización, persona que retira, motivo, hora y firma. Se elimina la planilla paralela.'},
 {route:'libro',title:'9. Todo termina en el Libro 3.0',script:'Abra el libro físico-digital: la planificación, asistencia, evaluaciones y observaciones convergen en una interfaz familiar y auditable.'},
 {route:'reportes',title:'10. Cierre: Control Tower',script:'Termine mostrando qué requiere atención hoy. La red gestiona excepciones y evidencia sin revisar libro por libro.'}
];
function startPresentation(){db.presentations={active:true,step:0,seconds:600,running:false};route=PRES[0].route;save();render();}
function renderPresentation(){document.getElementById('presentation')?.remove();const p=db.presentations,st=PRES[p.step];const d=document.createElement('div');d.id='presentation';d.className='presentation';d.innerHTML=`<div class="presTop"><div><div class="eyebrow" style="color:#9fd0f3">Guion · paso ${p.step+1}/${PRES.length}</div><div class="presTitle">${st.title}</div><div class="presScript">${st.script}</div></div><div class="presTimer" id="presTimer">${fmt(p.seconds)}</div></div><div class="presActions"><button onclick="togglePres()">${p.running?'Pausar':'Iniciar 10:00'}</button><button ${p.step===0?'disabled':''} onclick="presPrev()">←</button><button ${p.step===PRES.length-1?'disabled':''} onclick="presNext()">→</button><button style="background:#c82836;color:#fff" onclick="closePres()">Cerrar</button></div>`;document.body.appendChild(d);if(p.running)ensurePresTimer();}
function fmt(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function togglePres(){db.presentations.running=!db.presentations.running;save();if(db.presentations.running)ensurePresTimer();else clearInterval(presTimer);renderPresentation();}
function ensurePresTimer(){clearInterval(presTimer);presTimer=setInterval(()=>{if(!db.presentations.running)return clearInterval(presTimer);db.presentations.seconds=Math.max(0,db.presentations.seconds-1);document.getElementById('presTimer')&&(document.getElementById('presTimer').textContent=fmt(db.presentations.seconds));if(db.presentations.seconds===0){db.presentations.running=false;clearInterval(presTimer);}save();},1000);}
function presNext(){if(db.presentations.step>=PRES.length-1)return;db.presentations.step++;route=PRES[db.presentations.step].route;save();render();}
function presPrev(){if(db.presentations.step<=0)return;db.presentations.step--;route=PRES[db.presentations.step].route;save();render();}
function closePres(){clearInterval(presTimer);db.presentations.active=false;db.presentations.running=false;save();document.getElementById('presentation')?.remove();}

if('serviceWorker' in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
render();
